(function(E){ const x = E["exam-08"] = E["exam-08"] || {units:{}}; (x.units = x.units || {})["x08-s"] = {"id":"x08-s","patterns":["S1-frame","S1-people","S2-experience","S3-tech","TR-short","PARA-discuss"],"title":{"en":"Speaking","tr":"Speaking","fa":"Speaking (صحبت کردن)"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer everyday questions with a reason or an example, talk for two minutes about a conversation you had, and discuss the news with a view, a reason and an example.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: günlük soruları bir neden ya da örnekle cevaplayacak, yaptığın bir sohbet hakkında iki dakika konuşacak ve haberleri bir görüş, bir neden ve bir örnekle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های روزمره با یک دلیل یا مثال جواب بدهی، دو دقیقه درباره‌ی گفتگویی که داشتی حرف بزنی و درباره‌ی خبرها با یک نظر، یک دلیل و یک مثال بحث کنی."},"sessions":[["explain"],["sets"],["exit"]],"explain":{"title":{"en":"Speaking: Parts 1, 2 and 3","tr":"Speaking: Part 1, 2 ve 3","fa":"Speaking: بخش‌های ۱، ۲ و ۳"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer everyday questions with a reason or an example, talk for two minutes about a conversation you had, and discuss the news with a view, a reason and an example.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: günlük soruları bir neden ya da örnekle cevaplayacak, yaptığın bir sohbet hakkında iki dakika konuşacak ve haberleri bir görüş, bir neden ve bir örnekle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های روزمره با یک دلیل یا مثال جواب بدهی، دو دقیقه درباره‌ی گفتگویی که داشتی حرف بزنی و درباره‌ی خبرها با یک نظر، یک دلیل و یک مثال بحث کنی."},"stats":[{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"11-14 min","tr":"11-14 dk","fa":"۱۱ تا ۱۴ دقیقه"}},{"label":{"en":"Parts","tr":"Kısım","fa":"بخش"},"value":"3"},{"label":{"en":"Part 2 talk","tr":"Part 2 konuşması","fa":"صحبت Part 2"},"value":{"en":"2 min","tr":"2 dk","fa":"۲ دقیقه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: patience, a conversation, the news","tr":"Bu sınav: sabır, bir sohbet, haberler","fa":"این آزمون: صبر، یک گفتگو، خبرها"},"intro":{"en":"The three parts are linked: Part 1 is about you, Part 2 is one experience on a card, and Part 3 widens the Part 2 topic to people in general. Experiences are the most common Part 2 card.","tr":"Üç kısım birbirine bağlıdır: Part 1 seninle ilgili, Part 2 karttaki bir deneyim ve Part 3, Part 2 konusunu genel olarak insanlara genişletir. Deneyimler en sık çıkan Part 2 kartıdır.","fa":"سه بخش به هم وصل‌اند: Part 1 درباره‌ی خودت است، Part 2 یک تجربه روی کارت و Part 3 موضوع Part 2 را به آدم‌ها به‌طور کلی گسترش می‌دهد. تجربه‌ها رایج‌ترین کارت Part 2 هستند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x08-s1-ctx","exam":true,"patterns":["S1-frame","S1-people"],"often":{"pattern":"S1-people","n":9,"of":40,"label":{"en":"Comes up often in the real exam: 9 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 1: you, then patience","tr":"Part 1: sen, sonra sabır","fa":"Part 1: خودت، بعد صبر"},"asks":{"en":"The examiner checks your name and asks about your work, studies or home, then four questions on one everyday topic about people and personality. Here the topic is patience.","tr":"Sınav görevlisi adını kontrol eder, işini, okulunu ya da evini sorar, sonra insanlar ve kişilikle ilgili günlük bir konuda dört soru sorar. Burada konu sabır.","fa":"ممتحن اسمت را چک می‌کند، درباره‌ی کار، درس یا خانه‌ات می‌پرسد و بعد چهار سؤال درباره‌ی یک موضوع روزمره در مورد آدم‌ها و شخصیت. این‌جا موضوع صبر است."},"fields":["Work or studies","Home","Are you patient?","When you lose patience","Waiting","Patience and age"],"words":[{"a":"patient","b":"calm / I don’t mind waiting","tr":"sabırlı","fa":"صبور"},{"a":"impatient","b":"I hate waiting / I get restless","tr":"sabırsız","fa":"بی‌حوصله، کم‌صبر"},{"a":"lose my temper","b":"get annoyed / get irritated","tr":"sinirlenmek","fa":"از کوره در رفتن"},{"a":"queue","b":"wait in line","tr":"sırada beklemek","fa":"در صف ایستادن"},{"a":"it depends","b":"it depends on the situation / who I’m with","tr":"duruma bağlı","fa":"بستگی دارد"},{"a":"traffic jams","b":"being stuck in traffic","tr":"trafik sıkışıklığı","fa":"ترافیک سنگین"},{"a":"calm down","b":"take a deep breath / count to ten","tr":"sakinleşmek","fa":"آرام شدن"},{"a":"as I’ve got older","b":"these days / now that I’m older","tr":"yaşım ilerledikçe","fa":"هرچه بزرگ‌تر شده‌ام"},{"a":"to be honest","b":"actually / if I’m honest","tr":"açıkçası","fa":"راستش"},{"a":"a slow internet connection","b":"when pages take ages to load","tr":"yavaş internet","fa":"اینترنت کند"}],"traps":[{"en":"One-word answers: \"Yes.\" Add a reason or an example every time.","tr":"Tek kelimelik cevaplar: \"Yes.\" Her seferinde bir neden ya da örnek ekle.","fa":"جواب یک‌کلمه‌ای: «Yes.» هر بار یک دلیل یا مثال اضافه کن."},{"en":"A prepared speech. Part 1 is a conversation: two or three natural sentences are enough.","tr":"Ezberlenmiş bir konuşma. Part 1 bir sohbettir: iki üç doğal cümle yeter.","fa":"سخنرانی از پیش آماده‌شده. Part 1 یک گفتگوست: دو سه جمله‌ی طبیعی کافی است."}],"example":{"text":"Examiner: \"Are you a patient person?\"","item":"Which answer is best?","answer":"Mostly, yes. I don’t mind queuing, but I get impatient when my laptop is slow, especially if I have a deadline.","why":{"en":"An answer, a contrast and a concrete example, in two sentences.","tr":"İki cümlede bir cevap, bir karşıtlık ve somut bir örnek.","fa":"در دو جمله یک جواب، یک تضاد و یک مثال مشخص."}}},{"id":"x08-s2-ctx","exam":true,"patterns":["S2-experience"],"often":{"pattern":"S2-experience","n":17,"of":40,"label":{"en":"Comes up often in the real exam: 17 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 17’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 2: a long conversation about the news","tr":"Part 2: haberler hakkında uzun bir sohbet","fa":"Part 2: یک گفتگوی طولانی درباره‌ی یک خبر"},"asks":{"en":"The card asks you to describe a long conversation you had about something in the news. You have one minute to prepare and then talk for up to two minutes: who, what, why it was long, and what you felt about it.","tr":"Kart, haberlerdeki bir konu hakkında yaptığın uzun bir sohbeti anlatmanı istiyor. Hazırlanmak için bir dakikan var, sonra iki dakikaya kadar konuşursun: kiminle, ne hakkında, neden uzun sürdü ve ne hissettin.","fa":"کارت از تو می‌خواهد گفتگوی طولانی‌ای را که درباره‌ی یک خبر داشتی توصیف کنی. یک دقیقه برای آماده شدن داری و بعد تا دو دقیقه حرف می‌زنی: با چه کسی، درباره‌ی چه، چرا طول کشید و چه حسی داشتی."},"fields":["Who you talked to","What the news story was","Why the conversation went on so long","How you felt about it"],"words":[{"a":"a news story","b":"something in the headlines / on the news","tr":"bir haber","fa":"یک خبر"},{"a":"we got talking","b":"we started chatting / the subject came up","tr":"sohbete daldık","fa":"گرممان گرفت و حرف زدیم"},{"a":"we disagreed","b":"we saw it differently / we didn’t see eye to eye","tr":"anlaşamadık","fa":"هم‌نظر نبودیم"},{"a":"convince","b":"persuade / change someone’s mind","tr":"ikna etmek","fa":"قانع کردن"},{"a":"a heated discussion","b":"a lively argument","tr":"hararetli bir tartışma","fa":"بحثی داغ"},{"a":"it made me think","b":"it changed how I saw it","tr":"beni düşündürdü","fa":"به فکرم انداخت"},{"a":"before we knew it","b":"time flew / hours had passed","tr":"farkına bile varmadan","fa":"تا به خودمان بیاییم"},{"a":"the other side of the story","b":"a different point of view","tr":"işin öbür yüzü","fa":"روی دیگر ماجرا"},{"a":"in the end","b":"eventually / finally","tr":"sonunda","fa":"آخرش"},{"a":"looking back","b":"when I think about it now","tr":"geriye bakınca","fa":"وقتی حالا فکرش را می‌کنم"}],"traps":[{"en":"Explaining the news story for two minutes. The card is about the conversation: who said what, and why it went on.","tr":"İki dakika boyunca haberi anlatmak. Kart sohbetle ilgili: kim ne dedi ve neden uzadı.","fa":"دو دقیقه کامل خود خبر را توضیح دادن. کارت درباره‌ی گفتگوست: چه کسی چه گفت و چرا طول کشید."},{"en":"Forgetting the last line. \"Explain how you felt\" is where you reach two minutes.","tr":"Son satırı unutmak. \"Ne hissettiğini açıkla\" iki dakikaya ulaştığın yerdir.","fa":"فراموش کردن خط آخر. «توضیح بده چه حسی داشتی» جایی است که به دو دقیقه می‌رسی."}],"example":{"text":"Notes (one minute): uncle · new airport plan · dinner, 2 hours · jobs vs noise · he changed my mind a bit → felt respected","item":"How do you start?","answer":"I’d like to talk about a long conversation I had with my uncle last winter, about a plan to build a new airport near his town.","why":{"en":"One sentence answers who, when and what the story was.","tr":"Tek cümle kim, ne zaman ve haberin ne olduğunu cevaplıyor.","fa":"یک جمله به چه کسی، کی و چه خبری جواب می‌دهد."}}},{"id":"x08-s3-ctx","exam":true,"patterns":["S3-tech","PARA-discuss","TR-short"],"often":{"pattern":"S3-tech","n":5,"of":40,"label":{"en":"Comes up often in the real exam: 5 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 5’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۵ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 3: how people get the news","tr":"Part 3: insanlar haberleri nasıl alıyor","fa":"Part 3: مردم چطور خبر می‌گیرند"},"asks":{"en":"The examiner asks six general questions linked to the Part 2 topic: how people find out about the news today, and how local and international news compare.","tr":"Sınav görevlisi Part 2 konusuyla bağlantılı altı genel soru sorar: insanlar bugün haberleri nasıl öğreniyor ve yerel ile uluslararası haberler nasıl karşılaştırılır.","fa":"ممتحن شش سؤال کلی مرتبط با موضوع Part 2 می‌پرسد: امروز مردم چطور از خبرها باخبر می‌شوند و خبرهای محلی و بین‌المللی چه فرقی دارند."},"fields":["Sources of news","Age differences","Trust","Local news","International news","Discussion programmes"],"words":[{"a":"social media","b":"apps / online feeds","tr":"sosyal medya","fa":"شبکه‌های اجتماعی"},{"a":"reliable","b":"trustworthy / you can believe it","tr":"güvenilir","fa":"قابل اعتماد"},{"a":"headlines","b":"the main stories","tr":"manşetler","fa":"تیترها"},{"a":"fake news","b":"false stories / misleading reports","tr":"sahte haber","fa":"خبر جعلی"},{"a":"local news","b":"what happens in your town or area","tr":"yerel haberler","fa":"خبرهای محلی"},{"a":"international news","b":"events in other countries","tr":"uluslararası haberler","fa":"خبرهای بین‌المللی"},{"a":"in my view","b":"I’d say / personally, I think","tr":"bence","fa":"به نظر من"},{"a":"that said","b":"on the other hand / however","tr":"yine de","fa":"با این حال"},{"a":"for instance","b":"for example / take ... for example","tr":"örneğin","fa":"برای مثال"},{"a":"it varies","b":"it depends on the person / it differs","tr":"değişir","fa":"فرق می‌کند"}],"traps":[{"en":"A one-sentence answer. Part 3 needs a view, a reason and an example, and sometimes the other side.","tr":"Tek cümlelik cevap. Part 3 bir görüş, bir neden ve bir örnek, bazen de karşı tarafı ister.","fa":"جواب یک‌جمله‌ای. Part 3 نظر، دلیل و مثال می‌خواهد و گاهی طرف مقابل را."},{"en":"Talking only about yourself. Part 3 asks about people in general: \"most people\", \"young people\", \"in many countries\".","tr":"Yalnızca kendinden söz etmek. Part 3 genel olarak insanları sorar: \"most people\", \"young people\", \"in many countries\".","fa":"فقط درباره‌ی خودت حرف زدن. Part 3 درباره‌ی آدم‌ها به‌طور کلی می‌پرسد: «most people»، «young people»، «in many countries»."}],"example":{"text":"Examiner: \"Why do some people prefer local news to international news?\"","item":"What should the answer contain?","answer":"A view (it affects their daily life), a reason, an example (road closures, school news) and possibly the other side.","why":{"en":"These four moves turn a short reply into a full Part 3 answer.","tr":"Bu dört hamle kısa bir yanıtı tam bir Part 3 cevabına dönüştürür.","fa":"این چهار حرکت یک جواب کوتاه را به جوابی کامل برای Part 3 تبدیل می‌کنند."}}},{"id":"S2-exp-talk","ctx":["S2-experience","S2-exp-talk"],"title":{"en":"Conversations, news and information","tr":"Konuşmalar, haberler ve bilgi","fa":"گفتگو، خبر و اطلاعات"},"asks":{"en":"A card about something you heard, read or discussed: a claim you thought was false, a long discussion about news, an important conversation, a talk about spending money, a science programme.","tr":"Duyduğun, okuduğun ya da tartıştığın bir şey hakkında kart: yanlış olduğunu düşündüğün bir iddia, bir haber üzerine uzun bir tartışma, önemli bir konuşma, para harcama üzerine bir sohbet, bir bilim programı.","fa":"کارتی درباره‌ی چیزی که شنیدی، خواندی یا درباره‌اش بحث کردی: ادعایی که فکر می‌کردی غلط است، بحثی طولانی درباره‌ی یک خبر، گفتگویی مهم، صحبتی درباره‌ی خرج کردن پول، یک برنامه‌ی علمی."},"fields":["Describe a time you heard a claim you believed was false.","Describe a long conversation you had about a piece of news.","Describe an important discussion you had with a family member.","Describe a science programme you watched.","Describe a conversation about how to spend money."],"words":[{"a":"I heard","b":"I came across / someone told me","tr":"... duydum","fa":"شنیدم"},{"a":"it was not true","b":"it turned out to be false","tr":"yanlış çıktı","fa":"معلوم شد درست نیست"},{"a":"I checked","b":"I looked it up / I double-checked","tr":"kontrol ettim","fa":"چکش کردم"},{"a":"we talked","b":"we had a long discussion about","tr":"uzun uzun konuştuk","fa":"مفصل درباره‌اش حرف زدیم"},{"a":"we didn't agree","b":"we saw it differently","tr":"farklı düşünüyorduk","fa":"نظرمان فرق داشت"},{"a":"he said","b":"he argued that / he pointed out that","tr":"... olduğunu savundu","fa":"استدلال کرد که"},{"a":"in the end","b":"eventually we agreed that","tr":"sonunda ... konusunda anlaştık","fa":"آخرش توافق کردیم که"},{"a":"surprised","b":"I couldn't believe that","tr":"inanamadım","fa":"باورم نمی‌شد"},{"a":"I learned","b":"it opened my eyes to","tr":"gözlerimi ... açtı","fa":"چشمم را به ... باز کرد"},{"a":"serious","b":"an important decision","tr":"önemli bir karar","fa":"تصمیمی مهم"},{"a":"the news","b":"a news story / an article","tr":"bir haber","fa":"یک خبر"},{"a":"online","b":"on social media","tr":"sosyal medyada","fa":"در شبکه‌های اجتماعی"}],"traps":[{"en":"Reporting speech: \"he said that it was...\" (past). Do not act out the whole dialogue.","tr":"Aktarma: \"he said that it was...\" (geçmiş). Bütün diyaloğu canlandırma.","fa":"نقل قول غیرمستقیم: «he said that it was...» (گذشته). کل گفتگو را بازی نکن."},{"en":"The card asks about a conversation, not the topic in general: keep the people and the moment in your talk.","tr":"Kart genel olarak konuyu değil, bir konuşmayı sorar: konuşmadaki kişileri ve anı koru.","fa":"کارت درباره‌ی یک گفتگوست، نه کل موضوع: آدم‌ها و آن لحظه را در صحبتت نگه دار."}],"example":{"lines":[["Candidate","A few months ago my uncle told me that drinking coffee makes you shorter."],["Candidate","He said that he had read it in a magazine, so he was completely sure."],["Candidate","I looked it up that evening, and it turned out to be a very old myth."]],"item":"How is the uncle’s claim reported?","answer":"With reported speech: \"told me that...\", \"he said that he had read it\".","why":{"en":"Reported speech keeps the story in the past and moves faster than a dialogue.","tr":"Dolaylı anlatım hikâyeyi geçmişte tutar ve diyalogdan daha hızlı ilerler.","fa":"نقل قول غیرمستقیم داستان را در گذشته نگه می‌دارد و از گفتگوی کامل سریع‌تر جلو می‌رود."}},"ideas":["where and when the conversation happened","who said what (reported speech)","what you thought at the time","what happened next","why you still remember it (explain)"],"general":true,"patterns":["S2-experience"],"often":{"pattern":"S2-experience","n":17,"of":40,"label":{"en":"Comes up often in the real exam: 17 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 17’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۷ آزمون از ۴۰ آزمونِ اخیر"}}},{"id":"S3-tech","ctx":["S3-tech"],"title":{"en":"Technology and media","tr":"Teknoloji ve medya","fa":"فناوری و رسانه"},"asks":{"en":"General questions linked to the Part 2 card, about games, computers in class, the news, the internet and social media. The examiner wants an opinion, a reason, an example and, when it helps, the other side.","tr":"Part 2 kartına bağlı, oyunlar, sınıfta bilgisayar, haberler, internet ve sosyal medya hakkında genel sorular. Sınav görevlisi bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ister.","fa":"سؤال‌های کلی مرتبط با کارت Part 2، درباره‌ی بازی‌ها، کامپیوتر در کلاس، اخبار، اینترنت و شبکه‌های اجتماعی. ممتحن یک نظر، یک دلیل، یک مثال و هرجا لازم بود طرف مقابل را می‌خواهد."},"fields":["Are computer games good for children?","Should computers replace books in schools?","Where do young people get their news?","Has the internet made people less sociable?","Should social media be controlled?"],"words":[{"a":"online","b":"on the internet","tr":"çevrim içi","fa":"آنلاین"},{"a":"phones","b":"smartphones / devices","tr":"akıllı telefonlar","fa":"گوشی‌های هوشمند"},{"a":"news","b":"current affairs / headlines","tr":"güncel olaylar","fa":"اخبار روز"},{"a":"fake news","b":"misinformation","tr":"yanlış bilgi","fa":"اطلاعات نادرست"},{"a":"games","b":"video games","tr":"video oyunları","fa":"بازی‌های ویدئویی"},{"a":"use too much","b":"be addicted to","tr":"bağımlı olmak","fa":"معتاد بودن به"},{"a":"keep in touch","b":"stay connected","tr":"bağlantıda kalmak","fa":"در تماس ماندن"},{"a":"alone","b":"isolated","tr":"yalnız, yalıtılmış","fa":"منزوی"},{"a":"in class","b":"in the classroom","tr":"sınıfta","fa":"در کلاس"},{"a":"learn faster","b":"it speeds up learning","tr":"öğrenmeyi hızlandırır","fa":"یادگیری را سریع‌تر می‌کند"},{"a":"rules","b":"regulation / age limits","tr":"düzenleme, yaş sınırı","fa":"مقررات، محدودیت سنی"},{"a":"private","b":"personal data / privacy","tr":"kişisel veri","fa":"داده‌های شخصی"}],"traps":[{"en":"Avoid extreme answers (\"technology is destroying society\"). A balanced view sounds more convincing.","tr":"Uç cevaplardan kaçın (\"teknoloji toplumu yok ediyor\"). Dengeli bir görüş daha ikna edici olur.","fa":"از جواب‌های افراطی دوری کن («فناوری جامعه را نابود می‌کند»). دیدگاه متعادل قانع‌کننده‌تر است."},{"en":"Use \"it depends on\" with a real condition: age, time, how it is used.","tr":"\"It depends on\" ifadesini gerçek bir koşulla kullan: yaş, süre, nasıl kullanıldığı.","fa":"«it depends on» را با شرط واقعی به کار ببر: سن، زمان، طرز استفاده."}],"example":{"lines":[["Examiner","Are computer games good for children?"],["Candidate","It depends on how long they play."],["Candidate","An hour of a puzzle or building game can teach planning and patience."],["Candidate","But if children play every evening until midnight, it affects their sleep and their schoolwork."]],"item":"How does the speaker make \"it depends\" a full answer?","answer":"By naming the condition (how long), then giving a positive case and a negative case.","why":{"en":"\"It depends\" works only when you say what it depends on and show both cases.","tr":"\"It depends\" ancak neye bağlı olduğunu söyleyip iki durumu da gösterirsen işe yarar.","fa":"«it depends» فقط وقتی کار می‌کند که بگویی به چه بستگی دارد و هر دو حالت را نشان بدهی."}},"ideas":["games build problem-solving but take time from sport","screens help research, books help deep reading","social media connects people but spreads false news","age limits protect children"],"general":true,"patterns":["S3-tech"],"often":{"pattern":"S3-tech","n":5,"of":40,"label":{"en":"Comes up often in the real exam: 5 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 5’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۵ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Three parts, one examiner","tr":"Üç kısım, bir sınav görevlisi","fa":"سه بخش، یک ممتحن"},"body":{"en":"Part 1 (4-5 minutes): questions about you and one everyday topic. Part 2 (3-4 minutes): one minute to prepare, then up to two minutes alone, then one short question. Part 3 (4-5 minutes): a discussion of general questions. The test is recorded.","tr":"Part 1 (4-5 dakika): seninle ve günlük bir konuyla ilgili sorular. Part 2 (3-4 dakika): bir dakika hazırlık, sonra iki dakikaya kadar tek başına konuşma, sonra kısa bir soru. Part 3 (4-5 dakika): genel soruların tartışması. Sınav kaydedilir.","fa":"Part 1 (۴ تا ۵ دقیقه): سؤال‌هایی درباره‌ی خودت و یک موضوع روزمره. Part 2 (۳ تا ۴ دقیقه): یک دقیقه آماده شدن، بعد تا دو دقیقه حرف زدن به‌تنهایی و بعد یک سؤال کوتاه. Part 3 (۴ تا ۵ دقیقه): بحث درباره‌ی سؤال‌های کلی. آزمون ضبط می‌شود."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"One move for each part","tr":"Her kısım için bir hamle","fa":"برای هر بخش یک حرکت"},"steps":[{"en":"Part 1: answer, then add a reason or an example from your life.","tr":"Part 1: cevapla, sonra hayatından bir neden ya da örnek ekle.","fa":"Part 1: جواب بده، بعد یک دلیل یا مثال از زندگی‌ات اضافه کن."},{"en":"Part 2: note one key word for each line, and decide your feeling at the end before you start.","tr":"Part 2: her satır için bir anahtar kelime not et ve başlamadan önce sondaki duygunu belirle.","fa":"Part 2: برای هر خط یک کلیدواژه بنویس و قبل از شروع، حسِ آخر داستان را مشخص کن."},{"en":"Part 2: report what each person said: \"She argued that...\", \"I pointed out that...\".","tr":"Part 2: her kişinin ne dediğini aktar: \"She argued that...\", \"I pointed out that...\".","fa":"Part 2: حرف هر نفر را نقل کن: «She argued that...»، «I pointed out that...»."},{"en":"Part 3: talk about people in general, with a view, a reason and an example.","tr":"Part 3: genel olarak insanlardan söz et; bir görüş, bir neden ve bir örnekle.","fa":"Part 3: درباره‌ی آدم‌ها به‌طور کلی حرف بزن، با یک نظر، یک دلیل و یک مثال."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Reporting a conversation","tr":"Bir sohbeti aktarmak","fa":"نقل کردن یک گفتگو"},"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["what someone believed","He was convinced that the plan would create jobs."],["what you replied","I pointed out that the noise would affect thousands of people."],["agreeing in part","I could see his point, but..."],["how it ended","In the end we agreed to disagree."],["how you felt","I came away feeling that..."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"A Part 3 answer, step by step","tr":"Bir Part 3 cevabı, adım adım","fa":"یک جواب Part 3، قدم به قدم"},"instruction":"Examiner: \"Do young people and older people get their news in different ways?\"","item":"Answer with four moves.","answer":"Very much so. Most young people see the news on social media, often in short videos, while older people still tend to watch the evening bulletin. My grandmother, for instance, never misses it. That said, more and more older people are now reading the news on tablets.","walk":[{"en":"View: \"Very much so.\"","tr":"Görüş: \"Very much so.\"","fa":"نظر: «Very much so.»"},{"en":"Reason and example: social media for the young, the evening bulletin for the old; the grandmother.","tr":"Neden ve örnek: gençler için sosyal medya, yaşlılar için akşam bülteni; büyükanne.","fa":"دلیل و مثال: شبکه‌های اجتماعی برای جوان‌ها، بخش خبری شب برای مسن‌ترها؛ مادربزرگ."},{"en":"The other side: older people are moving online too.","tr":"Karşı taraf: yaşlılar da internete geçiyor.","fa":"طرف مقابل: مسن‌ترها هم دارند آنلاین می‌شوند."}]},"quick":{"prompt":"Part 1. Examiner: \"Do you get impatient in traffic?\" Which answer is best?","options":["Yes.","Traffic is a serious problem in most modern cities, and governments should invest more in public transport.","Sometimes, yes, especially when I’m late for work. I usually put on some music to stay calm."],"correct":2,"why":{"en":"A short answer with a detail. \"Yes.\" is too short; the answer about public transport talks about the city, not about you.","tr":"Ayrıntılı kısa bir cevap. \"Yes.\" çok kısa; toplu taşıma cevabı senden değil, şehirden söz ediyor.","fa":"یک جواب کوتاه با جزئیات. «Yes.» خیلی کوتاه است؛ جوابِ حمل‌ونقل عمومی درباره‌ی شهر است، نه خودت."}},"remember":{"en":"Part 1 short and personal, Part 2 who said what and how you felt, Part 3 people in general with reasons.","tr":"Part 1 kısa ve kişisel, Part 2 kim ne dedi ve ne hissettin, Part 3 nedenleriyle genel olarak insanlar.","fa":"Part 1 کوتاه و شخصی، Part 2 چه کسی چه گفت و چه حسی داشتی، Part 3 آدم‌ها به‌طور کلی با دلیل."},"type":"explain","id":"c-x08-s-e","course":"ielts-exams","exam":"exam-08","unit":"x08-s"},"sets":{"title":{"en":"The Speaking test","tr":"Speaking sınavı","fa":"آزمون Speaking"},"note":{"en":"Do the three parts in order, without a break, as in the real test. Record yourself if you can, then use the self-check under each part.","tr":"Gerçek sınavdaki gibi üç kısmı sırayla ve ara vermeden yap. Yapabilirsen kendini kaydet, sonra her kısmın altındaki öz değerlendirmeyi kullan.","fa":"سه بخش را به ترتیب و بدون مکث انجام بده، مثل آزمون واقعی. اگر می‌توانی صدایت را ضبط کن و بعد از خودارزیابیِ زیر هر بخش استفاده کن."},"sequential":true,"examinerVoice":{"accent":"British (standard Southern)","gender":"F","tts":{"engine":"kokoro","voice":"bf_alice"},"role":"Examiner"},"sets":[{"part":"Part 1","ctx":["S1-frame","S1-people"],"minutes":[4,5],"title":{"en":"Part 1: about you, then patience","tr":"Part 1: senin hakkında, sonra sabır","fa":"Part 1: درباره‌ی خودت، بعد صبر"},"examinerIntro":["Good afternoon. My name is Helen Ward. Can you tell me your full name, please?","Thank you. And can I see your identification, please?","Thank you. Now, in this first part, I’d like to ask you some questions about yourself."],"frame":["Let’s talk about what you do. Do you work or are you a student?","Why did you choose that job or subject?","What do you like most about the area where you live?"],"topicIntro":"Now let’s talk about patience.","questions":["Would you say you are a patient person?","What kinds of things make you feel impatient?","Have you become more patient as you have got older?","Do you think it is important for children to learn patience? [Why/Why not?]"],"model":"Q: Would you say you are a patient person?\nA: Mostly, yes. I don’t mind queuing or waiting for a bus, but I’m much less patient with technology, especially when my laptop freezes.\n\nQ: What kinds of things make you feel impatient?\nA: Slow internet, definitely, and people who walk very slowly in the middle of the pavement. I know it’s silly, but it really gets to me when I’m in a hurry.\n\nQ: Have you become more patient as you have got older?\nA: I think so. As a teenager I wanted everything immediately. Now I’ve learned that good things, like learning a language, take time.\n\nQ: Do you think it is important for children to learn patience?\nA: Absolutely. Life is full of waiting, and children who can wait calmly for their turn usually find school much easier.","moves":[{"label":{"en":"Answer first","tr":"Önce cevap","fa":"اول جواب"},"example":"Mostly, yes."},{"label":{"en":"Add a contrast or a detail","tr":"Bir karşıtlık ya da ayrıntı ekle","fa":"یک تضاد یا جزئیات اضافه کن"},"example":"I don’t mind queuing, but I’m much less patient with technology."},{"label":{"en":"Then and now","tr":"O zaman ve şimdi","fa":"آن موقع و حالا"},"example":"As a teenager I wanted everything immediately. Now I’ve learned that good things take time."}],"selfCheck":[{"en":"I answered every question with two or three sentences.","tr":"Her soruyu iki üç cümleyle cevapladım.","fa":"به هر سؤال با دو سه جمله جواب دادم."},{"en":"I gave a real example from my own life at least twice.","tr":"En az iki kez kendi hayatımdan gerçek bir örnek verdim.","fa":"دست‌کم دو بار مثالی واقعی از زندگی خودم آوردم."},{"en":"I used the present perfect correctly for changes (\"I’ve become\", \"I’ve learned\").","tr":"Değişimler için present perfect’i doğru kullandım (\"I’ve become\", \"I’ve learned\").","fa":"برای تغییرها حال کامل را درست به کار بردم («I’ve become»، «I’ve learned»)."}]},{"part":"Part 2","ctx":["S2-experience"],"minutes":[3,4],"title":{"en":"Part 2: a long conversation about the news","tr":"Part 2: haberler hakkında uzun bir sohbet","fa":"Part 2: یک گفتگوی طولانی درباره‌ی یک خبر"},"examinerIntro":["Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. Before you talk, you’ll have one minute to think about what you’re going to say. You can make some notes if you wish. Do you understand?","Here’s some paper and a pencil for making notes, and here’s your topic. I’d like you to describe a long conversation you had with someone about something in the news.","All right? Remember you have one to two minutes for this. Don’t worry if I stop you. I’ll tell you when the time is up. Can you start speaking now, please?"],"card":{"task":"Describe a long conversation you had with someone about something in the news.","bullets":["who you talked to","what the news story was about","why the conversation went on for a long time","and explain how you felt about the conversation"]},"prep":60,"talk":120,"roundingOff":["Do you often talk about the news with your friends?"],"model":"I’d like to talk about a long conversation I had with my uncle last winter, about a plan to build a new airport near the town where he lives.\n\nIt was a Sunday, and the whole family was at his house for lunch. The plan had been on the local news that morning, and my uncle was really excited about it. He’s retired now, but he used to run a small hotel, so he immediately started talking about all the jobs and visitors it would bring.\n\nI saw it rather differently. I pointed out that the planes would fly right over two villages, and that thousands of people would have to live with the noise. He argued that modern planes are much quieter, and then my cousin joined in with figures about traffic on the roads. Before we knew it, it was getting dark, and nobody had touched the dessert.\n\nThe reason it went on so long, I think, is that we both cared about the town, just in different ways. Neither of us was trying to win; we were really trying to understand the other side.\n\nAs for how I felt, I came away feeling quite good about it, which surprised me. We didn’t agree in the end, but he listened to me as an adult, and I realised that some of his points about jobs were stronger than I had thought. It’s rare to have a disagreement like that without anyone getting upset.","moves":[{"label":{"en":"Start with who, when and what","tr":"Kim, ne zaman ve ne ile başla","fa":"با چه کسی، کی و چه شروع کن"},"example":"I’d like to talk about a long conversation I had with my uncle last winter, about a plan to build a new airport."},{"label":{"en":"Report both sides of the conversation","tr":"Sohbetin iki tarafını da aktar","fa":"حرف هر دو طرف گفتگو را نقل کن"},"example":"I pointed out that the planes would fly right over two villages... He argued that modern planes are much quieter."},{"label":{"en":"Spend time on the explain line","tr":"Açıklama satırına zaman ayır","fa":"روی خط توضیح وقت بگذار"},"example":"As for how I felt, I came away feeling quite good about it, which surprised me."}],"selfCheck":[{"en":"I covered all four lines of the card and spoke for close to two minutes.","tr":"Kartın dört satırının hepsini ele aldım ve iki dakikaya yakın konuştum.","fa":"هر چهار خط کارت را گفتم و نزدیک دو دقیقه حرف زدم."},{"en":"I talked about the conversation, not only about the news story.","tr":"Yalnızca haberden değil, sohbetin kendisinden söz ettim.","fa":"درباره‌ی خودِ گفتگو حرف زدم، نه فقط خبر."},{"en":"I used reporting verbs (argued, pointed out, admitted) in the past.","tr":"Aktarma fiillerini (argued, pointed out, admitted) geçmiş zamanda kullandım.","fa":"فعل‌های نقل‌قول (argued، pointed out، admitted) را در زمان گذشته به کار بردم."}]},{"part":"Part 3","ctx":["S3-tech"],"minutes":[4,5],"title":{"en":"Part 3: getting the news","tr":"Part 3: haberleri öğrenmek","fa":"Part 3: خبر گرفتن"},"examinerIntro":["We’ve been talking about a conversation you had about the news, and I’d like to discuss with you one or two more general questions related to this."],"subtopics":[{"title":"How people get the news","questions":["What are the most common ways people get the news in your country?","Do young people and older people follow the news in different ways?","Why do some people stop following the news altogether?"]},{"title":"Local and international news","questions":["Why do some people prefer local news to international news?","Is it important to know what is happening in other countries? Why?","Do you think television discussion programmes help people understand the news?"]}],"model":"Q: Why do some people stop following the news altogether?\nA: I think the main reason is that it can be overwhelming. Most news is about problems that ordinary people can’t solve, so after a while some people simply feel anxious or helpless. A friend of mine deleted every news app from her phone last year for exactly that reason. That said, switching off completely has a cost, because you can miss information that really affects you, like changes to the law or to local services.\n\nQ: Is it important to know what is happening in other countries?\nA: Yes, more than ever, I’d say. Events in one country can affect prices, jobs and even the weather somewhere else, so it helps to understand the bigger picture. For example, a poor harvest in one region can push up the price of bread around the world. Of course, nobody can follow everything, but a basic idea of world events makes people better informed when they vote.","moves":[{"label":{"en":"Give a clear view","tr":"Net bir görüş ver","fa":"نظرت را روشن بگو"},"example":"I think the main reason is that it can be overwhelming."},{"label":{"en":"Support it: reason + example","tr":"Destekle: neden + örnek","fa":"پشتیبانی کن: دلیل + مثال"},"example":"A friend of mine deleted every news app from her phone last year for exactly that reason."},{"label":{"en":"Show the other side","tr":"Karşı tarafı göster","fa":"طرف مقابل را نشان بده"},"example":"That said, switching off completely has a cost..."}],"selfCheck":[{"en":"I gave a clear view in my first sentence.","tr":"İlk cümlemde net bir görüş verdim.","fa":"در جمله‌ی اولم نظر روشنی دادم."},{"en":"I supported it with a reason and an example.","tr":"Onu bir neden ve bir örnekle destekledim.","fa":"آن را با یک دلیل و یک مثال پشتیبانی کردم."},{"en":"I talked about people in general, not only about myself.","tr":"Yalnızca kendimden değil, genel olarak insanlardan söz ettim.","fa":"درباره‌ی آدم‌ها به‌طور کلی حرف زدم، نه فقط خودم."}]}],"type":"sets","id":"c-x08-s-p","course":"ielts-exams","exam":"exam-08","unit":"x08-s"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"I lose my temper in traffic.\" This means the speaker...","options":["gets lost","gets angry","gets bored"],"correct":1,"why":{"en":"Lose your temper = become angry.","tr":"Lose your temper = sinirlenmek.","fa":"lose your temper یعنی عصبانی شدن."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase means \"we did not agree\"?","options":["we didn’t see eye to eye","we saw each other often","we looked at the news together"],"correct":0,"why":{"en":"Not see eye to eye = disagree.","tr":"Not see eye to eye = aynı fikirde olmamak.","fa":"not see eye to eye یعنی هم‌نظر نبودن."}},{"tests":"method","point":2,"prompt":"Part 2 card: \"a conversation about something in the news\". What should take most of your two minutes?","options":["a full summary of the news story","facts about newspapers","the conversation and how you felt"],"correct":2,"why":{"en":"The card is about the conversation; the news story is only the background.","tr":"Kart sohbetle ilgili; haber yalnızca arka plan.","fa":"کارت درباره‌ی گفتگوست؛ خبر فقط زمینه است."}},{"tests":"trap","point":2,"prompt":"Part 3: \"Why do people follow international news?\" A candidate says: \"I don’t really watch the news.\" What is missing?","options":["A longer story about the candidate","A view about people in general, with a reason and an example","Nothing: it answers the question"],"correct":1,"why":{"en":"Part 3 asks about people in general; a personal habit does not answer it.","tr":"Part 3 genel olarak insanları sorar; kişisel bir alışkanlık soruyu cevaplamaz.","fa":"Part 3 درباره‌ی آدم‌ها به‌طور کلی می‌پرسد؛ یک عادت شخصی جوابش نیست."}},{"tests":"method","point":2,"prompt":"Which sentence reports what someone said in the conversation?","options":["He argued that the airport would bring jobs.","He is a nice man.","The airport is near the town."],"correct":0,"why":{"en":"\"He argued that...\" reports his point of view.","tr":"\"He argued that...\", onun görüşünü aktarıyor.","fa":"«He argued that...» دیدگاه او را نقل می‌کند."}}],"id":"c-x08-s-x","course":"ielts-exams","exam":"exam-08","unit":"x08-s"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
